<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Administração · PY9MT Energia</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#0c111a;color:#e8eff9;font:15px system-ui}main{max-width:1200px;margin:auto;padding:28px 24px}header{display:flex;justify-content:space-between;gap:20px;align-items:center;flex-wrap:wrap}.brand{color:#60dfbe;font-size:13px;letter-spacing:1px}h1{margin:8px 0;font-size:28px}h2{font-size:21px;margin-top:0}p,small{color:#9aacc1;line-height:1.6}a{color:#8dd9ff;text-decoration:none}a:hover{text-decoration:underline}nav{display:flex;gap:12px;flex-wrap:wrap;margin:28px 0}nav a,button,.button{border:1px solid #40516a;border-radius:7px;padding:10px 16px;background:#18273b;color:#e8eff9;font:inherit;cursor:pointer}nav a[aria-current=page],button.primary,.button.primary{background:#60dfbe;color:#0c1726;border-color:#60dfbe;font-weight:650}article{background:#141f2e;border:1px solid #29394f;border-radius:12px;padding:24px}.head-row{display:flex;justify-content:space-between;gap:16px;align-items:center;flex-wrap:wrap}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;min-width:650px}td,th{padding:14px 12px;border-bottom:1px solid #29394f;text-align:left;font-weight:400}th{color:#9aacc1;font-size:13px}.active{color:#60dfbe}.inactive{color:#ffbc65}label{display:block;margin:18px 0 7px}input,select{width:100%;padding:11px;background:#0c1726;border:1px solid #40516a;border-radius:6px;color:#e8eff9;font:inherit}input[type=checkbox]{width:auto}input:focus,select:focus{outline:2px solid #60dfbe}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 24px}.actions{display:flex;gap:12px;align-items:center;margin-top:28px}.error,.success{padding:14px;border-radius:7px;line-height:1.5}.error{background:#3b252b;color:#ffc1b5}.success{background:#153b34;color:#92efcc}.version{font:12px ui-monospace,monospace;color:#9aacc1}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-width:500px;font-size:12px}.top-links{display:flex;align-items:center;gap:18px;flex-wrap:wrap}@media(max-width:650px){main{padding:20px 14px}.form-grid{grid-